using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SphotoApp.Web.Data; using SphotoApp.Web.ViewModels; namespace SphotoApp.Web.Controllers; [Authorize] public class HomeController(AppDbContext db):Controller { public async Task<IActionResult> Index(){var h=await db.DownloadHistories.OrderByDescending(x=>x.StartedAt).ToListAsync();return View(new DashboardVm{Latest=h.FirstOrDefault(),Recent=h.Take(5).ToList(),TotalCount=h.Count,CustomerCount=await db.Customers.CountAsync(),TodayCount=h.Count(x=>x.StartedAt.Date==DateTime.UtcNow.Date)});} }
